import {createIcons,LayoutDashboard,ChartNoAxesCombined,Globe,Newspaper,Bookmark,Database,Search,ArrowUpRight,ArrowRight,ArrowDown,ArrowUp,RefreshCw,ChevronRight,ChevronLeft,ChevronDown,Plus,X,Download,Maximize2,Minimize2,MoreHorizontal,MousePointer2,Minus,TrendingUp,SlidersHorizontal,Bell,Check,ExternalLink,Activity,Menu,Settings2,Trash2,FileText,Upload,Target,Layers,MoveUpRight,Grid2X2,Info,Wifi,WifiOff,Clock,Star} from 'lucide';

