const icons={LayoutDashboard,ChartNoAxesCombined,Globe,Newspaper,Bookmark,Database,Search,ArrowUpRight,ArrowRight,ArrowDown,ArrowUp,RefreshCw,ChevronRight,ChevronLeft,ChevronDown,Plus,X,Download,Maximize2,Minimize2,MoreHorizontal,MousePointer2,Minus,TrendingUp,SlidersHorizontal,Bell,Check,ExternalLink,Activity,Menu,Settings2,Trash2,FileText,Upload,Target,Layers,MoveUpRight,Grid2X2,Info,Wifi,WifiOff,Clock,Star};

const $=s=>document.querySelector(s);const storage=safeStorage();let workspace=readState(storage);const data={markets:null,global:null,sentiment:null,news:null,chains:null,exchange:null};const errors={};let instruments={binance:[],coinbase:[]};let page='overview',terminal=null,mini=null,visuals=[],pageGeneration=0,marketPage=0,marketQuery='',marketSort='rank',marketUniverse='aggregate',onlyWatch=false,newsQuery='',newsSource='all',loading=false;

let selected=workspace.preferences.lastInstrument;let selectedInterval=workspace.preferences.interval;let comparison=null,noteTimer=null,studioViewName='map';let modalGeneration=0,studioGeneration=0;const alertPrices=new Map();let learning=null,marketStream=null,miniSeries=null;let appearance=applyAppearance(readAppearance(storage),storage);

let dockMode=readDock(storage),newsLimit=20;const dataLoader=createDataLoader(k=>api(k==='exchange'?'exchange-markets':k),data,errors);

function hydrate(){createIcons({icons,attrs:{'stroke-width':1.7}});}

function save(){const ok=writeState(storage,workspace);if(!ok)toast('Browser storage is unavailable or full. Export a backup to keep your work.');return ok;}

function meta(key){const r=data[key];return r?`${r.provider} · ${r.cache==='stale'?'STALE · ':''}snapshot · ${ago(r.data?.updatedAt??r.fetchedAt)}`:errors[key]?'Data unavailable':'Connecting…';}

function stateBadge(key){return `<span class="source ${data[key]?.cache==='stale'?'warn':''}" title="${esc(data[key]?stamp(data[key].fetchedAt):errors[key]??'Awaiting response')}">${esc(meta(key))}</span>`;}

function empty(message,detail=''){return `<div class="empty-state">${icon('database')}<strong>${esc(message)}</strong><p>${esc(detail)}</p></div>`;}

function errorOrLoading(key){return errors[key]?empty('Data unavailable',errors[key]+' · Use Refresh to retry.'):empty('Loading data','');}

function coinMark(symbol){return `<span class="coin-mark" aria-hidden="true">${esc(symbol.slice(0,2))}</span>`;}

function header(title,description,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function syncDockAccess(){const dock=$('.sidebar');if(dock)dock.inert=dockMode==='hidden';}
function setDock(mode){dockMode=normalizeDock(mode);document.body.dataset.dock=dockMode;syncDockAccess();saveDock(storage,dockMode);const expand=$('[data-action="dock-expand"]');if(expand){expand.setAttribute('aria-expanded',dockMode==='expanded');expand.setAttribute('aria-label',dockMode==='expanded'?'Collapse navigation':'Expand navigation');}const toggle=$('[data-action="dock-toggle"]');if(toggle)toggle.setAttribute('aria-label',dockMode==='hidden'?'Show navigation':dockMode==='expanded'?'Collapse navigation':'Expand navigation');}
function secondaryNav(){const group=groupFor(page),items=GROUPS[group];return `<nav class="context-nav" aria-label="${PRIMARY.find(x=>x.id===group).label} tools">${items.map((x,i)=>x.target?`<button data-action="section" data-target="${x.target}" aria-pressed="${i===0}">${x.label}</button>`:`<a href="#${x.route}" ${x.route===page?'aria-current="page"':''}>${x.label}</a>`).join('')}${page==='overview'?`<button class="context-section-link" data-action="section" data-target="home-markets">Market overview ${icon('arrow-down')}</button>`:''}</nav>`;}
function shell(){
 $('#app').innerHTML=`<aside class="sidebar" id="navigation-dock" aria-label="Navigation dock"><a href="#overview" class="dock-brand" aria-label="CRYPTOZ Home"><span class="brand-mark">Z</span><span class="dock-brand-name" aria-hidden="true">CRYPTOZ</span></a><nav aria-label="Primary">${PRIMARY.map(x=>`<a href="#${x.route}" data-group="${x.id}" aria-label="${x.label}">${icon(x.icon)}<span class="dock-label" aria-hidden="true">${x.label}</span><span class="dock-tip" aria-hidden="true">${x.label}</span></a>`).join('')}</nav><div class="dock-controls"><button class="icon-button" data-action="dock-expand" aria-controls="navigation-dock" aria-expanded="false" aria-label="Expand navigation" title="Expand or collapse labels">${icon('chevron-right')}</button><button class="icon-button" data-action="dock-hide" aria-label="Hide navigation" title="Hide navigation">${icon('chevron-left')}</button></div></aside><div class="main-shell"><header class="topbar"><button class="icon-button dock-header-toggle" data-action="dock-toggle" aria-controls="navigation-dock" aria-label="Expand navigation">${icon('menu')}</button><a href="#overview" class="topbar-brand" aria-label="CRYPTOZ Home">CRYPTOZ</a><button class="search-trigger" data-action="search" aria-label="Search coins and instruments">${icon('search')}<span>Search coins</span><kbd>/</kbd></button><div class="top-actions"><button class="icon-button appearance-button" data-action="appearance" aria-label="Appearance settings" title="Theme and motion">${icon('settings-2')}</button><button class="icon-button" title="Refresh data" aria-label="Refresh data" data-action="refresh">${icon('refresh-cw')}</button><a href="#workspace" class="icon-button" aria-label="Workspace alerts">${icon('bell')}<span id="alert-count"></span></a></div></header><div id="context-root"></div><main id="main" tabindex="-1"></main><footer class="footer"><span>CRYPTOZ</span><span><a href="https://coinpaprika.com/" target="_blank" rel="noopener noreferrer">Powered by Coinpaprika</a> · <a href="/legal/notices.txt" target="_blank" rel="noopener noreferrer">Licenses</a></span></footer></div>`;
 setDock(dockMode);hydrate();
}

async function fetchData(keys=['markets','global','sentiment','news']){
 loading=true;document.body.classList.add('refreshing');await dataLoader.load(keys);loading=dataLoader.busy;document.body.classList.toggle('refreshing',loading);
 if(page==='markets')renderMarketResults();else if(page==='news')renderNewsResults();else if(page==='studio')studioView(studioViewName);else if(page==='overview')updateHomeData();else if(page==='workspace')updateWorkspacePrices();else if(page==='terminal')updateWatchPanel();
}

async function loadInstruments(){await Promise.allSettled(['binance','coinbase'].map(async v=>{try{instruments[v]=(await api('instruments?venue='+v)).data;}catch(e){errors['instruments-'+v]=e.message;}}));if(page==='terminal')updateInstrumentOptions();if(page==='compare')comparison?.updateInstruments();learning?.updateInstruments();marketStream?.setRegistry(instruments.binance);}

function cleanPage(){document.body.classList.remove('chart-focus');flushNote();learning?.dispose();learning=null;miniSeries=null;comparison?.dispose();comparison=null;terminal?.dispose();terminal=null;mini?.remove();mini=null;for(const v of visuals)v.dispose();visuals=[];}

function route(){page=resolveRoute(location.hash);marketPage=0;document.body.classList.remove('menu-open');renderPage();window.scrollTo({top:0,behavior:'instant'});$('.main-shell')?.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function renderPage(){
 cleanPage();pageGeneration++;const group=groupFor(page);document.querySelectorAll('[data-group]').forEach(a=>{const active=a.dataset.group===group;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#context-root').innerHTML=secondaryNav();
 ({overview:renderOverview,markets:renderMarkets,terminal:renderTerminal,compare:renderComparison,studio:renderStudio,learn:renderLearning,news:renderNews,workspace:renderWorkspace}[page])();hydrate();updateAlertCount();patchLiveQuotes();
}

function liveStrip(){return `<section class="live-strip" aria-label="Live Binance prices"><div class="live-strip-label"><strong>SPOT / USDT</strong><small class="live-status" data-live-status>Connecting to live prices…</small></div>${['BTC','ETH','SOL','BNB','XRP'].map(b=>`<button class="live-quote" data-action="live-chart" data-symbol="${b}USDT" data-live-chip="${b}USDT" aria-label="Open ${b} live chart"><span>${b} / USDT</span><strong>—</strong><small>Awaiting quote</small></button>`).join('')}</section>`;}
function patchLiveStatus(s){if(!marketStream?.fresh('BTCUSDT')&&$('#benchmark-change small')?.textContent==='live price · 24h')$('#benchmark-change small').textContent='last price · awaiting update';const fresh=s?.state==='streaming';for(const el of document.querySelectorAll('[data-live-status]')){el.dataset.state=s?.state??'connecting';el.textContent=fresh?'● Live Binance · ~1s':s?.state==='delayed'?'Delayed · showing last price':s?.state==='reconnecting'?'Reconnecting · last price retained':'Connecting to live prices…';}for(const el of document.querySelectorAll('[data-live-chip]')){const q=marketStream?.fresh(el.dataset.liveChip);if(!q&&el.querySelector('strong').textContent!=='—')el.querySelector('small').textContent='Last price · awaiting update';}for(const row of document.querySelectorAll('[data-live-row]')){const q=marketStream?.quotes.get(row.dataset.liveRow);const el=row.querySelector('[data-live-time]');if(q&&el){el.textContent=marketStream.fresh(q.symbol)?'Live · '+ago(q.updatedAt):'Last · '+ago(q.updatedAt);el.title=stamp(q.updatedAt);}}}
function patchLiveQuotes(){if(!marketStream)return;for(const el of document.querySelectorAll('[data-live-chip]')){const q=marketStream.fresh(el.dataset.liveChip);if(!q)continue;el.querySelector('strong').textContent=num(q.price,q.price<1?6:2);const d=el.querySelector('small');d.textContent=pct(q.change)+' · 24h';d.className=tone(q.change);}for(const row of document.querySelectorAll('[data-live-row]')){const q=marketStream.fresh(row.dataset.liveRow);if(!q)continue;row.querySelector('[data-live-price]').textContent=price(q.price,'');const d=row.querySelector('[data-live-change]');d.textContent=pct(q.change);d.classList.remove('positive','negative');d.classList.add(tone(q.change));row.querySelector('[data-live-volume]').textContent=compact(q.volume);const t=row.querySelector('[data-live-time]');t.textContent='Live · '+ago(q.updatedAt);t.title=stamp(q.updatedAt);}const q=marketStream.fresh('BTCUSDT');if(q&&$('#benchmark-price')){$('#benchmark-price').textContent=num(q.price)+' USDT';$('#benchmark-change').innerHTML=`<span class="${tone(q.change)}">${pct(q.change)}</span><small>live price · 24h</small>`;}marketStream.report();}
function appearanceModal(){modal('Appearance',`<div class="appearance-options"><label>Color theme<select id="appearance-theme"><option value="dark">Midnight glass · blue / violet</option><option value="light">Glacier glass · light / cobalt</option></select></label><label>Motion<select id="appearance-motion"><option value="auto">Follow device preference</option><option value="reduced">Reduce motion</option></select></label><p class="data-note">Saved on this browser.</p></div>`);$('#appearance-theme').value=appearance.theme;$('#appearance-motion').value=appearance.motion;const update=()=>{appearance=applyAppearance({theme:$('#appearance-theme').value,motion:$('#appearance-motion').value},storage);if(terminal?.bars.length)terminal.build();comparison?.applyTheme();learning?.applyTheme();if(mini){mini.applyOptions(chartOptions());miniSeries?.applyOptions({lineColor:palette().accent,topColor:palette().accent+'30',bottomColor:palette().accent+'00'});}if(page==='studio')studioView(studioViewName);};$('#appearance-theme').addEventListener('change',update);$('#appearance-motion').addEventListener('change',update);}
function renderLearning(){$('#main').innerHTML=header('Signals & guides','Indicator readings and practical chart guides.')+'<div id="learning-root"></div>';learning=mountLearning($('#learning-root'),{instruments,hydrate,onChart:i=>{selected=i;location.hash='terminal';}});}

function newsToolbar(){return `<div class="news-toolbar"><div class="tabs" aria-label="News publishers">${['all','CoinDesk','Decrypt','Cointelegraph'].map(n=>`<button class="tab ${newsSource===n?'active':''}" data-action="news-source" data-source="${n}" aria-pressed="${newsSource===n}">${n==='all'?'All publishers':n}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="news-search" aria-label="Search news" placeholder="Search news" value="${esc(newsQuery)}"></label></div>`;}
function bindNewsSearch(){const field=$('#news-search');if(field)field.addEventListener('input',e=>{newsQuery=e.target.value;newsLimit=20;renderNewsResults();});}
function marketStats(){const g=data.global?.data,s=data.sentiment?.data;return `<div class="stats-grid"><article class="stat-card"><span>Market cap ${icon('globe')}</span><div>${g?'$'+compact(g.marketCap):'—'}</div><p class="${tone(g?.change)}">${pct(g?.change)} <small>24h</small></p>${stateBadge('global')}</article><article class="stat-card"><span>Trading volume ${icon('chart-no-axes-combined')}</span><div>${g?'$'+compact(g.volume):'—'}</div><p class="muted">24-hour volume</p>${stateBadge('global')}</article><article class="stat-card"><span>Bitcoin dominance ${icon('layers')}</span><div>${g?num(g.btcDominance)+'<small>%</small>':'—'}</div><div class="dominance-track"><span style="width:${g?.btcDominance??0}%"></span></div>${stateBadge('global')}</article><article class="stat-card"><span>Fear & Greed ${icon('activity')}</span><div>${s?num(s.value,0)+'<small>/ 100</small>':'—'}</div><p>${s?esc(s.label):'Awaiting index'}</p>${stateBadge('sentiment')}</article></div>`;}
function breadthContent(){const assets=data.markets?.data??[],top=assets.slice(0,100),up=top.filter(x=>x.change>0).length,down=top.filter(x=>x.change<0).length;return `<div class="panel-top"><h2>Market breadth</h2>${icon('activity')}</div><p class="muted">24h change · top ${top.length||'—'} assets</p><div class="breadth-numbers"><span class="positive">${top.length?up:'—'}<small>Advancing</small></span><span class="negative">${top.length?down:'—'}<small>Declining</small></span></div><div class="breadth-track"><span style="width:${top.length?up/top.length*100:0}%"></span></div><div class="pulse-divider"></div><div class="pulse-item"><span>Tracked assets</span><strong>${assets.length?num(assets.length,0):'—'}</strong></div>${stateBadge('markets')}<a href="#studio" class="button full">Market maps ${icon('arrow-right')}</a>`;}
function renderOverview(){
 $('#main').innerHTML=header('Latest news','Crypto, policy and macro market headlines.')+`<section aria-label="Latest news">${newsToolbar()}<div id="news-results" class="news-reading-panel"></div><div id="home-news-meta" class="news-update-note">${stateBadge('news')}</div></section><section class="home-market-section" id="home-markets" aria-labelledby="home-market-title"><div class="section-title"><div><h2 id="home-market-title">Market overview</h2><p>Live exchange prices and market totals.</p></div><div class="related-actions"><a href="#markets" class="button">Prices ${icon('arrow-up-right')}</a><a href="#studio" class="button">Market maps ${icon('layers')}</a></div></div>${liveStrip()}<div id="home-totals">${marketStats()}</div><div class="overview-chart-grid"><section class="panel feature-chart"><div class="panel-top"><h2>${coinMark('BTC')} Bitcoin <span>BTC / USDT</span></h2><a href="#terminal" data-action="default-chart" class="text-link">Open chart ${icon('arrow-up-right')}</a></div><div class="benchmark-quote"><strong id="benchmark-price">—</strong><span id="benchmark-change"></span><div class="range-pills"><span>1h candles</span><span>Binance</span></div></div><div id="benchmark-chart" class="benchmark-chart"></div><div class="panel-bottom"><span id="benchmark-source">Loading chart…</span><span>Drag to pan · Scroll to zoom</span></div></section><aside class="panel market-pulse" id="home-breadth">${breadthContent()}</aside></div><div class="section-title"><h2>Leading assets</h2><a href="#markets" class="text-link">All prices ${icon('arrow-right')}</a></div><section class="panel market-panel"><div id="overview-table">${data.markets?marketTable(data.markets.data.slice(0,8)):errorOrLoading('markets')}</div></section><div class="section-title"><div><h2>Research tools</h2><p>Chart analysis, comparisons and indicator guides.</p></div><div class="related-actions"><a href="#terminal" class="button">Chart ${icon('chart-no-axes-combined')}</a><a href="#compare" class="button">Compare ${icon('layers')}</a><a href="#learn" class="button">Signals & guides ${icon('file-text')}</a></div></div></section>`;
 bindNewsSearch();renderNewsResults();loadBenchmark(pageGeneration);
}
function updateHomeData(){if(page!=='overview'||!$('#home-totals'))return;renderNewsResults();$('#home-news-meta').innerHTML=stateBadge('news');$('#home-totals').innerHTML=marketStats();$('#home-breadth').innerHTML=breadthContent();$('#overview-table').innerHTML=data.markets?marketTable(data.markets.data.slice(0,8)):errorOrLoading('markets');loadBenchmark(pageGeneration);hydrate();}
async function loadBenchmark(gen){
 try{const r=await api('candles?venue=binance&symbol=BTCUSDT&interval=1h');if(gen!==pageGeneration||page!=='overview')return;const {createChart,AreaSeries}=await import('lightweight-charts');if(gen!==pageGeneration)return;const bars=r.data.bars;
  if(!mini){$('#benchmark-chart').innerHTML='';mini=createChart($('#benchmark-chart'),{autoSize:true,...chartOptions(),layout:{...chartOptions().layout,fontSize:11,attributionLogo:true},grid:{vertLines:{visible:false},horzLines:{color:palette().grid}},rightPriceScale:{borderVisible:false},timeScale:{borderVisible:false,timeVisible:true}});miniSeries=mini.addSeries(AreaSeries,{lineColor:palette().accent,topColor:palette().accent+'30',bottomColor:palette().accent+'00',lineWidth:2,priceLineVisible:false,lastValueVisible:false});miniSeries.setData(bars.slice(-168).map(b=>({time:b.time,value:b.close})));mini.timeScale().fitContent();}else miniSeries.setData(bars.slice(-168).map(b=>({time:b.time,value:b.close})));
  $('#benchmark-price').textContent=num(bars.at(-1).close)+' USDT';const change=(bars.at(-1).close/bars.at(-25)?.close-1)*100;$('#benchmark-change').innerHTML=`<span class="${tone(change)}">${pct(change)}</span><small>24h candles</small>`;$('#benchmark-source').textContent=`Binance · ${r.cache==='stale'?'Stale history':'1h history'} · ${stamp(r.fetchedAt)}`;patchLiveQuotes();
 }catch(e){if(gen===pageGeneration&&$('#benchmark-chart')&&!mini)$('#benchmark-chart').innerHTML=empty('Chart unavailable',e.message);}
}

function marketTable(assets,venue=false){return `<div class="table-scroll"><table class="market-table"><thead><tr><th class="col-watch"><span class="sr-only">Watchlist</span></th><th>Asset</th><th>Price (${venue?'USDT':'USD'})</th><th class="col-change">24h</th>${venue?'':'<th class="col-cap">Market cap</th>'}<th class="col-volume">24h volume</th><th class="col-action"></th></tr></thead><tbody>${assets.map(a=>`<tr ${venue?'data-live-row="'+esc(a.id)+'"':''}><td class="col-watch"><button class="star-button ${workspace.watchlist.includes(a.id)?'selected':''}" data-action="watch" data-id="${esc(a.id)}" aria-label="${workspace.watchlist.includes(a.id)?'Remove':'Add'} ${esc(a.symbol)} ${workspace.watchlist.includes(a.id)?'from':'to'} watchlist" aria-pressed="${workspace.watchlist.includes(a.id)}">${icon('star')}</button></td><td><button class="asset-name" data-action="${venue?'exchange-chart':'asset-chart'}" data-id="${esc(a.id)}">${coinMark(a.symbol)}<span><strong>${esc(venue?a.symbol:a.name)}</strong><small>${esc(venue?a.name:a.symbol)}${a.rank?' · #'+a.rank:''}</small></span></button></td><td class="mono"><span class="price-value" ${venue?'data-live-price':''}>${price(a.price,venue?'':'$')}</span><small class="col-time" ${venue?'data-live-time':''} title="${esc(stamp(a.updatedAt))}">${ago(a.updatedAt)}</small></td><td class="col-change ${tone(a.change)} mono" ${venue?'data-live-change':''}>${pct(a.change)}</td>${venue?'':`<td class="mono col-cap">$${compact(a.marketCap)}</td>`}<td class="mono col-volume" ${venue?'data-live-volume':''}>${venue?'':'$'}${compact(a.volume)}</td><td class="col-action"><button class="icon-button" data-action="${venue?'exchange-chart':'asset-chart'}" data-id="${esc(a.id)}" aria-label="Chart ${esc(a.symbol)}">${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}

function renderMarkets(){

 $('#main').innerHTML=header('Prices','Search crypto assets and open exchange charts.',`<button class="button" data-action="export-markets">${icon('download')} Export results</button>`)+`<div class="panel"><div class="market-controls"><div class="tabs"><button class="tab ${marketUniverse==='aggregate'?'active':''}" data-action="universe" data-universe="aggregate">Asset directory <span>USD</span></button><button class="tab ${marketUniverse==='exchange'?'active':''}" data-action="universe" data-universe="exchange">Binance spot <span>USDT</span></button></div><label class="search-field">${icon('search')}<input id="market-search" placeholder="Search name, symbol or asset ID" value="${esc(marketQuery)}" aria-label="Search markets"></label></div><div class="filter-row"><button class="chip ${onlyWatch?'selected':''}" data-action="toggle-watch">${icon('star')} Watchlist only</button><label class="sort-label">Sort by <select id="market-sort"><option value="rank">${marketUniverse==='exchange'?'Volume':'Rank'}</option>${marketUniverse==='aggregate'?'<option value="marketCap">Market cap</option>':''}<option value="volume">24h volume</option><option value="gainers">Top gainers</option><option value="losers">Top losers</option></select></label><span id="market-source"></span><span class="live-status" data-live-status></span></div><div id="market-results"></div><div id="market-pagination" class="pagination"></div></div><p class="data-note">Directory prices are aggregate USD snapshots. Binance prices use USDT; live rows show their update time. Sorting updates on refresh or filter change.</p>`;

 $('#market-sort').value=marketSort;$('#market-search').addEventListener('input',e=>{marketQuery=e.target.value;marketPage=0;renderMarketResults();});$('#market-sort').addEventListener('change',e=>{marketSort=e.target.value;marketPage=0;renderMarketResults();});renderMarketResults();if(marketUniverse==='exchange'&&!data.exchange)fetchData(['exchange']);

}

function filteredMarkets(){const list=[...(marketUniverse==='exchange'?(data.exchange?.data??[]).map(a=>{const q=marketStream?.fresh(a.id);return q?{...a,...q,id:a.id,symbol:a.symbol}:a;}):data.markets?.data??[])].filter(a=>(!onlyWatch||workspace.watchlist.includes(a.id))&&`${a.name} ${a.symbol} ${a.id}`.toLowerCase().includes(marketQuery.toLowerCase()));if(marketSort==='marketCap')list.sort((a,b)=>(b.marketCap??0)-(a.marketCap??0));if(marketSort==='volume')list.sort((a,b)=>b.volume-a.volume);if(marketSort==='gainers')list.sort((a,b)=>(b.change??-Infinity)-(a.change??-Infinity));if(marketSort==='losers')list.sort((a,b)=>(a.change??Infinity)-(b.change??Infinity));return list;}

function renderMarketResults(){const key=marketUniverse==='exchange'?'exchange':'markets';const list=filteredMarkets(),pages=Math.max(1,Math.ceil(list.length/40));marketPage=Math.min(marketPage,pages-1);$('#market-results').innerHTML=list.length?marketTable(list.slice(marketPage*40,marketPage*40+40),marketUniverse==='exchange'):data[key]?empty('No assets match your filters','Try a name, ticker or a different universe.'):errorOrLoading(key);$('#market-source').innerHTML=stateBadge(key);$('#market-pagination').innerHTML=`<span>${num(list.length,0)} results · Page ${marketPage+1} of ${pages}</span><div><button class="icon-button" data-action="prev-page" aria-label="Previous page" ${marketPage===0?'disabled':''}>${icon('chevron-left')}</button><button class="icon-button" data-action="next-page" aria-label="Next page" ${marketPage>=pages-1?'disabled':''}>${icon('chevron-right')}</button></div>`;hydrate();patchLiveQuotes();}

function capturePreferences(){if(!terminal)return;workspace.preferences=normalizePreferences({lastInstrument:selected,interval:selectedInterval,view:terminal.viewPreset,style:terminal.style,period:terminal.period,rsiPeriod:terminal.rsiPeriod,oscillator:terminal.oscillator,indicators:terminal.indicators,markers:terminal.markers});save();}

function refreshIndicatorStrip(){if(!terminal||!$('#indicator-strip'))return;const active=Object.keys(terminal.indicators).filter(k=>terminal.indicators[k]);$('#indicator-strip').innerHTML=`<span>${active.length} overlay${active.length===1?'':'s'} · ${terminal.oscillator.toUpperCase()}${terminal.markers?' · EMA crosses':''}</span><small id="chart-window-info">Loading history…</small>`;terminal.notifyWindow();}
function updateChartWindow(info){const el=$('#chart-window-info');if(!el)return;if(!info.total){el.textContent='Loading history…';return;}const short=t=>new Date(t*1000).toLocaleDateString(undefined,{month:'short',day:'numeric',timeZone:'UTC'});el.textContent=`${info.visible} / ${info.total} candles · ${short(info.start)}–${short(info.end)} UTC`;const select=$('#chart-view');if(select)select.value=info.selection??'custom';}
function setChartFocus(value){document.body.classList.toggle('chart-focus',value);const b=$('#focus-chart');if(b){b.innerHTML=icon(value?'minimize-2':'maximize-2');b.setAttribute('aria-label',value?'Exit chart focus':'Focus chart');b.setAttribute('aria-pressed',value);}hydrate();requestAnimationFrame(()=>terminal?.draw());}

function flushNote(){clearTimeout(noteTimer);if($('#research-note')&&['Saving…','Not saved · export a backup'].includes($('#note-status')?.textContent)){$('#note-status').textContent=save()?'Saved on this browser':'Not saved · export a backup';}}

function resetRisk(){const f=$('#risk-form');if(!f)return;for(const n of ['entry','stop','target'])f.elements[n].value='';$('#risk-result').textContent='Instrument changed. Enter levels for '+selected.base+' / '+selected.quote+'.';}

function renderComparison(){ $('#main').innerHTML=header('Compare','Compare price changes and risk over the same period.')+'<div id="comparison-root"></div>';comparison=mountComparison($('#comparison-root'),{instruments,hydrate});}

function layoutModal(){if(!terminal)return;modal('Saved chart layouts',`<p class="muted">Layouts save indicators, chart style, interval and instrument on this browser.</p><form id="layout-form"><label>Layout name<input name="name" required maxlength="60" placeholder="e.g. Momentum research"></label><button class="button primary" type="submit">Save current layout</button></form><div class="layout-list">${workspace.layouts.map(l=>`<div class="layout-row"><span><strong>${esc(l.name)}</strong><small>${esc(l.settings.lastInstrument.symbol)} · ${esc(l.settings.interval)} · ${esc(l.settings.style)}</small></span><button class="button" data-action="load-layout" data-id="${esc(l.id)}">Load</button><button class="icon-button" data-action="delete-layout" data-id="${esc(l.id)}" aria-label="Delete ${esc(l.name)} layout">${icon('trash-2')}</button></div>`).join('')||'<p class="muted">No named layouts yet. Current settings auto-save automatically.</p>'}</div>`);$('#layout-form').addEventListener('submit',e=>{e.preventDefault();if(workspace.layouts.length>=8){toast('Maximum 8 named layouts. Delete one to save another.');return;}capturePreferences();workspace.layouts.push({id:crypto.randomUUID(),name:new FormData(e.target).get('name').trim(),settings:structuredClone(workspace.preferences)});save();layoutModal();});}

function renderTerminal(){

 $('#main').innerHTML=`<div class="terminal-heading"><div><h1>Chart</h1></div><span class="source" id="stream-status">Connecting…</span></div><div class="chart-section-links"><button data-action="section" data-target="terminal-chart">Price chart</button><button data-action="section" data-target="risk-tools">Risk calculator</button><button data-action="section" data-target="research-note">Notes & alerts</button></div><div class="terminal-layout" id="terminal-chart"><section class="panel terminal-main"><div class="instrument-bar"><label class="select-wrap"><span>Venue</span><select id="venue"><option value="binance">Binance</option><option value="coinbase">Coinbase</option></select></label><label class="select-wrap instrument-select"><span>Instrument</span><select id="instrument" aria-label="Chart instrument"></select></label><button class="icon-button" data-action="search" title="Search all instruments" aria-label="Search all instruments">${icon('search')}</button><div class="instrument-quote"><strong id="terminal-price">—</strong><span id="terminal-change"></span><small id="compact-stream-status" role="status">Connecting</small></div><div class="instrument-stats"><span>24h high <b id="terminal-high">—</b></span><span>24h low <b id="terminal-low">—</b></span></div></div><div class="chart-toolbar"><div class="timeframes">${['1m','5m','15m','1h','4h','1d'].map(t=>`<button data-action="timeframe" data-time="${t}" class="${t===selectedInterval?'selected':''}">${t.endsWith('m')?t:t.toUpperCase()}</button>`).join('')}</div><label class="compact-timeframe"><span class="sr-only">Candle interval</span><select id="compact-interval">${['1m','5m','15m','1h','4h','1d'].map(t=>`<option value="${t}" ${t===selectedInterval?'selected':''}>${t.toUpperCase()}</option>`).join('')}</select></label><label class="chart-view-control"><span>View</span><select id="chart-view" aria-label="Chart view"><option value="all">All history</option><option value="recent">100 bars</option><option value="custom" disabled>Custom</option></select></label><div class="chart-zoom" aria-label="Chart zoom"><button class="icon-button" data-action="zoom-out" aria-label="Zoom out" title="Zoom out">${icon('minus')}</button><button class="icon-button" data-action="zoom-in" aria-label="Zoom in" title="Zoom in">${icon('plus')}</button></div><button class="tool-button study-button" data-action="indicators" aria-label="Indicators">${icon('sliders-horizontal')}<span>Indicators</span></button><details class="chart-menu"><summary aria-label="Chart tools">${icon('more-horizontal')}<span>Tools</span></summary><div class="chart-menu-body"><label>Chart type<select id="chart-style" aria-label="Chart style"><option value="candles">Candles</option><option value="bars">OHLC bars</option><option value="line">Line</option><option value="heikin">Heikin-Ashi</option></select></label><button data-action="layouts">${icon('layers')} Saved layouts</button><button data-action="drawings">${icon('settings-2')} Manage drawings</button><button data-action="fit-chart">${icon('maximize-2')} Reset view</button><button data-action="chart-png">${icon('download')} Export PNG</button><button data-action="chart-csv">${icon('download')} Export candles CSV</button></div></details><button class="icon-button focus-button" id="focus-chart" data-action="focus-chart" aria-label="Focus chart" aria-pressed="false" title="Focus chart">${icon('maximize-2')}</button></div><div class="indicator-strip" id="indicator-strip"><span>EMA 20</span><span>EMA 50</span><span>RSI 14</span><small>UTC bars · provisional latest candle</small></div><div class="chart-workspace"><div class="drawing-tools">${[['cursor','mouse-pointer-2','Pan and crosshair'],['horizontal','minus','Horizontal level'],['trend','trending-up','Trend line: two clicks'],['fib','layers','Fibonacci: two clicks'],['label','file-text','Annotation: one click']].map(([id,i,t])=>`<button class="icon-button ${id==='cursor'?'selected':''}" data-action="draw-tool" data-tool="${id}" title="${t}" aria-label="${t}">${icon(i)}</button>`).join('')}<span></span><button class="icon-button" data-action="drawings" title="Edit saved drawings" aria-label="Edit saved drawings">${icon('settings-2')}</button></div><div class="price-chart" id="price-chart" aria-label="Interactive price chart"></div></div><div class="chart-bottom"><span id="candle-source">Drag to pan · wheel to zoom · drawings save per instrument/timeframe</span><button class="text-link" data-action="drawings">Drawings <span id="drawings-count">0</span> ${icon('chevron-right')}</button></div><div class="technical-panel"><div class="technical-header"><div><h3>Technical context</h3></div><span class="source">Completed candles</span></div><div id="technical-summary" class="technical-grid"></div></div></section><aside class="terminal-side"><section class="panel orderbook-panel"><div class="panel-top"><h2>Order book</h2><span class="small-tag" id="book-mode">L2 SNAPSHOT</span></div><div class="book-labels"><span>Price</span><span>Size (base)</span><span>Total</span></div><div id="orderbook">${empty('Connecting…')}</div><div class="book-footer" id="book-source">Refreshing every 15s</div></section><section class="panel"><div class="panel-top"><h2>My watchlist</h2><a href="#markets" class="icon-button" aria-label="Add watchlist coins">${icon('plus')}</a></div><div id="terminal-watchlist"></div></section></aside></div><div class="terminal-lower"><section class="panel risk-panel" id="risk-tools"><div class="panel-top"><div><h2>Risk calculator</h2></div>${icon('target')}</div><form id="risk-form"><div class="risk-inputs"><label>Direction<select name="side"><option value="long">Long</option><option value="short">Short</option></select></label><label>Equity (quote)<input name="equity" type="number" min="0.01" step="any" value="10000" required></label><label>Risk (%)<input name="riskPercent" type="number" min="0.01" max="100" step="any" value="1" required></label><label>Entry<input name="entry" type="number" min="0.00000001" step="any" required placeholder="Entry price"></label><label>Stop loss<input name="stop" type="number" min="0.00000001" step="any" required placeholder="Invalidation"></label><label>Target<input name="target" type="number" min="0.00000001" step="any" required placeholder="Target price"></label><label>Fee / side (%)<input name="feePercent" type="number" min="0" max="10" step="any" value="0.1" required></label></div><div class="form-action"><button class="button primary" type="submit">Calculate risk ${icon('arrow-right')}</button><button class="button" type="button" data-action="use-price">Use current price</button></div><div id="risk-result" class="risk-result">Enter levels to estimate position size and fees. Slippage and funding are excluded.</div></form></section><section class="panel note-panel"><div class="panel-top"><div><h2>Research notes</h2></div><span id="note-status" class="source">Browser local</span></div><label class="sr-only" for="research-note">Research note for this instrument</label><textarea id="research-note" placeholder="Add research notes…" maxlength="10000"></textarea><div class="form-action"><button class="button" data-action="save-note">Save note</button><button class="button" data-action="new-alert">${icon('bell')} Price alert</button></div><p class="data-note">Saved on this browser. Alerts require an open tab.</p></section></div>`;

 terminal=new TerminalChart({host:$('#price-chart'),workspace,save,onQuote:updateQuote,onSummary:updateSummary,onBook:updateBook,onStatus:updateStreamStatus,onWindow:updateChartWindow,onDrawings:()=>{if($('#drawings-count'))$('#drawings-count').textContent=(workspace.drawings[terminal?.key]??[]).length;}});

 $('#venue').value=selected.venue;$('#chart-style').value=terminal.style;$('#chart-view').value=terminal.viewPreset;refreshIndicatorStrip();updateInstrumentOptions();capturePreferences();terminal.load(selected,selectedInterval);updateWatchPanel();loadNote();

 $('#venue').addEventListener('change',e=>{flushNote();const previousBase=selected.base;selected=selectVenueInstrument(selected,instruments[e.target.value],e.target.value);if(selected.base!==previousBase)toast(previousBase+' is not listed here; selected '+selected.base+'.');capturePreferences();resetRisk();updateInstrumentOptions();terminal.load(selected,selectedInterval);loadNote();});

 $('#instrument').addEventListener('change',e=>{flushNote();selected=instruments[selected.venue].find(x=>x.symbol===e.target.value)??selected;capturePreferences();resetRisk();terminal.load(selected,selectedInterval);loadNote();});

 $('#chart-view').addEventListener('change',e=>{terminal.setViewPreset(e.target.value);capturePreferences();});$('#compact-interval').addEventListener('change',e=>{selectedInterval=e.target.value;capturePreferences();document.querySelectorAll('[data-action="timeframe"]').forEach(b=>b.classList.toggle('selected',b.dataset.time===selectedInterval));terminal.load(selected,selectedInterval);});
 $('#chart-style').addEventListener('change',e=>{terminal.style=e.target.value;capturePreferences();if(terminal.bars.length)terminal.build();});

 $('#risk-form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(values))if(k!=='side')values[k]=+values[k];try{const r=planRisk(values);$('#risk-result').innerHTML=`<div class="risk-metrics"><span>Position size<strong>${num(r.quantity,8)} ${esc(selected.base)}</strong></span><span>Risk budget<strong>${num(r.budget)} ${esc(selected.quote)}</strong></span><span>Reward / risk<strong>${num(r.rewardRisk)} : 1</strong></span><span>Notional<strong>${num(r.notional)} ${esc(selected.quote)}</strong></span></div><p>${r.capitalExceeded?'<span class="negative">Notional exceeds equity. This plan requires leverage or a smaller position.</span>':'Fee-inclusive estimate at your chosen levels.'} Short positions require a suitable borrowing or derivative facility. No order is placed.</p>`;}catch(error){$('#risk-result').textContent=error.message;}});

 $('#research-note').addEventListener('input',()=>{workspace.notes[`${selected.venue}:${selected.symbol}`]=$('#research-note').value;$('#note-status').textContent='Saving…';clearTimeout(noteTimer);noteTimer=setTimeout(()=>{const ok=save();if($('#note-status'))$('#note-status').textContent=ok?'Saved on this browser':'Not saved · export a backup';},400);});

}

function updateInstrumentOptions(){if(!$('#instrument'))return;const items=[...instruments[selected.venue]];if(!items.some(x=>x.symbol===selected.symbol))items.unshift(selected);items.sort((a,b)=>a.base.localeCompare(b.base));$('#instrument').innerHTML=items.map(x=>`<option value="${esc(x.symbol)}">${esc(x.base)}/${esc(x.quote)}</option>`).join('');$('#instrument').value=selected.symbol;}

function updateQuote(q){if(!$('#terminal-price'))return;$('#terminal-price').textContent=q?`${num(q.price,q.price<1?8:4)} ${selected.quote}`:'—';$('#terminal-change').innerHTML=q?.change!==undefined&&q?.change!==null?`<span class="${tone(q.change)}">${pct(q.change)}</span><small>24h</small>`:'';$('#terminal-high').textContent=q?.high?num(q.high,6):'—';$('#terminal-low').textContent=q?.low?num(q.low,6):'—';if(q&&!q.stale&&q.source!=='candle')evaluateAlerts(selected,q.price,q.updatedAt);}

function updateSummary(s){if(!$('#technical-summary'))return;$('#technical-summary').innerHTML=s.ready?`<div><span>Trend · EMA 20 / 50</span><strong class="${s.trend==='Uptrend'?'positive':s.trend==='Downtrend'?'negative':''}">${s.trend}</strong><small>${num(s.ema20,4)} / ${num(s.ema50,4)}</small></div><div><span>RSI (14) · Wilder</span><strong>${num(s.rsi)}</strong><small>${s.momentum}</small></div><div><span>MACD histogram</span><strong class="${tone(s.macd)}">${num(s.macd,6)}</strong><small>12 / 26 / 9</small></div><div><span>ATR (14)</span><strong>${num(s.atr,6)}</strong><small>${num(s.volatility)}% of last close</small></div>`:'<p class="muted">At least 50 completed candles are needed. Sparse history is not interpolated.</p>';}

function updateStreamStatus(s){if(!$('#stream-status'))return;const compact=$('#compact-stream-status');if(compact){const short={loading:'Connecting',streaming:'Live',snapshot:'Snapshot',polling:'Reconnecting',delayed:'Delayed',stale:'Stale',unavailable:'Unavailable'}[s]??s;if(compact.textContent!==short)compact.textContent=short;compact.dataset.status=s;}const labels={loading:'Connecting to exchange…',streaming:'WebSocket · live messages',snapshot:'REST snapshot',polling:'REST fallback · reconnecting',delayed:'Delayed · awaiting fresh data',stale:'Stale provider cache',unavailable:'Provider unavailable'};$('#stream-status').innerHTML=`<span class="live-dot ${s==='streaming'?'':'muted-dot'}"></span>${labels[s]??s}`;$('#stream-status').className='source '+(['stale','delayed','unavailable'].includes(s)?'warn':'');if(terminal?.candleMeta)$('#candle-source').textContent=`${terminal.candleMeta.provider} · ${selected.base}/${selected.quote} · UTC bars · ${terminal.candleMeta.cache==='stale'?'STALE · ':''}${stamp(terminal.candleMeta.fetchedAt)}`;}

function updateBook(r){if(!$('#orderbook'))return;if(!r){$('#book-mode').textContent='AWAITING DATA';$('#orderbook').innerHTML=empty('Book unavailable','Awaiting next valid snapshot.');$('#book-source').textContent='No current snapshot';return;}$('#book-mode').textContent=r.cache==='live'?'LIVE · TOP 20':'L2 SNAPSHOT';const d=r.data,max=Math.max(...d.bids.slice(0,7).map(x=>x[1]),...d.asks.slice(0,7).map(x=>x[1]),1);const rows=(items,side)=>items.map(x=>`<div class="book-row ${side}" style="--depth:${x[1]/max*100}%"><span>${num(x[0],x[0]<1?8:2)}</span><span>${num(x[1],5)}</span><span>${compact(x[0]*x[1])}</span></div>`).join('');const bid=d.bids[0]?.[0],ask=d.asks[0]?.[0];$('#orderbook').innerHTML=rows(d.asks.slice(0,7).reverse(),'ask')+`<div class="book-spread">Spread <strong>${Number.isFinite(ask-bid)?num(ask-bid,8):'—'} ${esc(selected.quote)}</strong><small>${bid&&ask?num((ask-bid)/((ask+bid)/2)*100,4)+'%':''}</small></div>`+rows(d.bids.slice(0,7),'bid');$('#book-source').textContent=`${r.provider} · ${r.cache==='stale'?'STALE · ':''}${r.cache==='live'?'received '+new Date(r.fetchedAt).toLocaleTimeString():ago(r.fetchedAt)} · top 7 / side`;}

function updateWatchPanel(){if(!$('#terminal-watchlist'))return;const list=(data.markets?.data??[]).filter(a=>workspace.watchlist.includes(a.id));$('#terminal-watchlist').innerHTML=list.length?list.slice(0,8).map(a=>`<button class="watch-row" data-action="asset-chart" data-id="${esc(a.id)}"><span>${esc(a.symbol)} <small>USD</small></span><span>${price(a.price)}<small class="${tone(a.change)}">${pct(a.change)}</small></span></button>`).join(''):empty('Watchlist empty','Star an asset in Markets to save it.');}

function loadNote(){if($('#research-note')){$('#research-note').value=workspace.notes[`${selected.venue}:${selected.symbol}`]??'';$('#note-status').textContent='Browser local';}}

function newsCards(items){return items.map((n,i)=>{const tag=classifyHeadline(n.title);return `<article class="news-card"><div class="news-card-top"><span class="publisher-mark">${esc(n.source.slice(0,1))}</span><span>${esc(n.source)}</span><time title="${esc(stamp(n.publishedAt))}">${ago(n.publishedAt)}</time></div><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer" class="news-headline">${esc(n.title)}${icon('arrow-up-right')}</a><div class="news-card-bottom"><span class="news-tag">${tag}</span></div></article>`;}).join('');}

function classifyHeadline(t){if(/fed\b|inflation|interest rate|treasury|dollar|cpi\b/i.test(t))return 'MACRO';if(/regulat|sec\b|law|legislat|court|policy/i.test(t))return 'POLICY';if(/hack|exploit|security|breach/i.test(t))return 'SECURITY';if(/etf|fund|institution/i.test(t))return 'INSTITUTIONAL';if(/defi|protocol|ethereum|solana/i.test(t))return 'ECOSYSTEM';return 'MARKETS';}

function renderNews(){$('#main').innerHTML=header('News','Crypto, regulation and macro market headlines.')+newsToolbar()+'<div id="news-results" class="news-reading-panel"></div><div class="news-update-note">'+stateBadge('news')+'</div>';bindNewsSearch();renderNewsResults();}
function renderNewsResults(){if(!$('#news-results'))return;for(const id of ['#news-data-meta','#home-news-meta'])if($(id))$(id).innerHTML=stateBadge('news');const result=newsWindow(data.news?.data.items??[],{source:newsSource,query:newsQuery,limit:page==='overview'?5:newsLimit});$('#news-results').innerHTML=result.items.length?newsCards(result.items)+(page==='news'?`<div class="news-load"><span>${result.items.length} of ${result.total} headlines</span>${result.remaining?`<button class="button" data-action="news-more">Show more (${Math.min(20,result.remaining)})</button>`:''}</div>`:''):data.news?empty('No matching headlines','Try another publisher or search.'):errorOrLoading('news');hydrate();}

async function renderStudio(){

 const gen=pageGeneration;$('#main').innerHTML=header('Market maps','View market size, liquidity and network activity.',`<a href="#terminal" class="button">${icon('chart-no-axes-combined')} Open terminal</a>`)+`<div class="studio-tabs"><button class="chip selected" data-action="studio-tab" data-view="map">Market map</button><button class="chip" data-action="studio-tab" data-view="momentum">Liquidity & momentum</button><button class="chip" data-action="studio-tab" data-view="defi">DeFi landscape</button><button class="chip" data-action="studio-tab" data-view="depth">Exchange depth</button></div><div id="studio-content"></div>`;await studioView(studioViewName,gen);

}

async function studioView(view,gen=pageGeneration){studioViewName=view;

 const viewGen=++studioGeneration;const current=()=>gen===pageGeneration&&viewGen===studioGeneration;

 for(const v of visuals)v.dispose();visuals=[];document.querySelectorAll('[data-action="studio-tab"]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));const el=$('#studio-content');if(!el)return;

 const definitions={map:['Market capitalization map','Area = market cap. Color = 24h price change. Top 45 directory assets. Click an asset to choose its exchange chart.'],momentum:['Liquidity meets momentum','24h change vs reported USD trading volume (log scale). Bubble size = market cap. First 100 qualifying ranked assets.'],defi:['Where DeFi capital sits','Chain TVL is sourced from DeFiLlama. TVL depends on the provider methodology and can include overlapping protocol exposures.'],depth:[`${selected.base} / ${selected.quote} · depth snapshot`,'Cumulative base-asset size within the first 50 bid/ask levels. A partial snapshot, not total market liquidity.']};

 el.innerHTML=`<div class="studio-grid"><section class="panel"><div class="panel-top"><div><h2>${esc(definitions[view][0])}</h2></div><span class="small-tag">OBSERVED DATA</span></div><p class="chart-description">${esc(definitions[view][1])}</p><div id="studio-chart" class="studio-chart"></div><div id="studio-meta" class="panel-bottom"></div></section><aside class="panel studio-insights"><div class="panel-top"><h2>Reading this view</h2>${icon('info')}</div><div id="studio-insights"></div><a href="#markets" class="button full">View prices ${icon('arrow-up-right')}</a></aside></div>`;hydrate();

 try{const {createVisual}=await import('./visuals.js');if(!current())return;let payload,kind,key;

  if(view==='defi'){if(!data.chains)data.chains=await api('chains');payload=data.chains.data;kind='chains';key='chains';}

  else if(view==='depth'){const r=await api(`book?venue=${selected.venue}&symbol=${selected.symbol}`);if(!current())return;payload=r.data;kind='depth';key=null;$('#studio-meta').textContent=`${r.provider} · ${r.cache==='stale'?'STALE · ':''}${stamp(r.fetchedAt)}`;}

  else {if(!data.markets)throw Error(errors.markets??'Market prices are loading. Use Refresh to retry.');payload=data.markets.data;kind=view==='map'?'treemap':'scatter';key='markets';}

  if(!current()||!$('#studio-chart'))return;visuals.push(createVisual($('#studio-chart'),kind,payload,{onSelect:id=>chooseAsset(id)}));if(key)$('#studio-meta').innerHTML=stateBadge(key);

  const a=data.markets?.data??[];const total=a.reduce((s,x)=>s+(x.marketCap??0),0);$('#studio-insights').innerHTML=view==='defi'?`<div class="insight-number">${payload.length}<small>chains reporting positive TVL</small></div><p>Compare the largest chain networks by reported capital locked.</p><div class="callout">TVL is not market cap, revenue or a valuation. Do not sum chains to assert unique deposits.</div>`:view==='depth'?`<div class="insight-number">50<small>levels requested per side</small></div><p>${esc(selected.venue.toUpperCase())} · ${esc(selected.symbol)}</p><div class="callout">Displayed orders can be canceled. Depth is a point-in-time snapshot and does not predict trade execution.</div>`:`<div class="insight-number">${a.length?num(a.length,0):'—'}<small>directory assets in snapshot</small></div><div class="pulse-item"><span>Top 10 cap share</span><strong>${total?num(a.slice(0,10).reduce((s,x)=>s+(x.marketCap??0),0)/total*100)+'%':'—'}</strong></div><p>Concentration and liquidity are different. Smaller assets can carry large execution risk.</p><div class="callout">${view==='map'?'A small tile can still have a large percentage move. Color is not a trade signal.':'Reported turnover is not audited executable liquidity. Log scaling spreads orders of magnitude.'}</div>${stateBadge('markets')}`;

 }catch(e){if(current()&&$('#studio-chart'))$('#studio-chart').innerHTML=empty('Visualization unavailable',e.message);}

}

function renderWorkspace(){const list=(data.markets?.data??[]).filter(a=>workspace.watchlist.includes(a.id));$('#main').innerHTML=header('Workspace','Watchlist, alerts, notes and journal.',`<div class="inline-actions"><button class="button" data-action="export-workspace">${icon('download')} Backup</button><button class="button" data-action="import-workspace">${icon('upload')} Import</button><button class="button" data-action="restore-workspace">Recover import</button></div>`)+`<div class="callout workspace-callout">${icon('info')} Saved on this browser. Backups are unencrypted.</div><section class="panel" id="workspace-watchlist"><div class="panel-top"><h2>Watchlist <span class="count">${workspace.watchlist.length}</span></h2><a href="#markets" class="text-link">Add assets ${icon('plus')}</a></div><div id="workspace-watchlist-table">${data.markets?list.length?marketTable(list):empty('Watchlist empty','Star an asset in Prices to save it.'):errorOrLoading('markets')}</div></section><div class="workspace-grid"><section class="panel" id="workspace-alerts"><div class="panel-top"><div><h2>Price alerts</h2></div><button class="button" data-action="new-alert">${icon('plus')} Add alert</button></div><div id="alerts-list">${alertList()}</div><p class="data-note">Triggers once when a fresh price crosses the threshold. Keep this tab open.</p></section><section class="panel" id="workspace-journal"><div class="panel-top"><h2>Journal</h2>${icon('file-text')}</div><form id="journal-form"><label class="sr-only" for="journal-text">Research journal entry</label><textarea id="journal-text" maxlength="4000" placeholder="Add a journal entry…" required></textarea><button class="button primary" type="submit">Save entry ${icon('plus')}</button></form><div class="journal-list">${workspace.journal.slice().reverse().slice(0,15).map(j=>`<article><time>${esc(stamp(j.createdAt))}</time><button class="icon-button" data-action="delete-journal" data-id="${esc(j.id)}" aria-label="Delete journal entry">${icon('trash-2')}</button><p>${esc(j.text)}</p></article>`).join('')}</div></section></div><section class="panel saved-notes"><div class="panel-top"><h2>Saved instrument notes</h2></div>${Object.entries(workspace.notes).filter(([k,v])=>v.trim()).map(([k,v])=>`<article><span class="eyebrow">${esc(k)}</span><p>${esc(v)}</p></article>`).join('')||empty('No saved notes yet','Add a note in Chart.')}</section><input id="workspace-file" type="file" accept="application/json,.json" class="hidden">`;

 $('#journal-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#journal-text').value.trim();if(!text)return;workspace.journal.push({id:crypto.randomUUID(),text,createdAt:new Date().toISOString()});workspace.journal=workspace.journal.slice(-200);save();renderPage();});$('#workspace-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Maximum backup size is 2 MB');const imported=validateWorkspace(JSON.parse(await f.text()));try{storage.setItem(RECOVERY_KEY,JSON.stringify(workspace));}catch{throw Error('Cannot create recovery backup; import canceled. Export your workspace first.');}workspace=imported;selected=workspace.preferences.lastInstrument;selectedInterval=workspace.preferences.interval;alertPrices.clear();save();toast('Workspace imported.');renderPage();}catch(err){toast('Import rejected: '+err.message);}});

}

function updateWorkspacePrices(){if(!$('#workspace-watchlist-table'))return;const list=(data.markets?.data??[]).filter(x=>workspace.watchlist.includes(x.id));$('#workspace-watchlist-table').innerHTML=data.markets?list.length?marketTable(list):empty('Watchlist empty','Star an asset in Prices to save it.'):errorOrLoading('markets');$('#workspace-watchlist .count').textContent=workspace.watchlist.length;hydrate();}

function alertList(){return workspace.alerts.length?workspace.alerts.map(a=>`<article class="alert-row"><div>${icon('bell')}<span><strong>${esc(a.symbol)}</strong><small>${esc(a.venue)} · ${a.direction} ${num(a.target,8)} · ${a.active?'Armed':a.triggeredAt?'Triggered '+ago(a.triggeredAt):'Paused'}</small></span></div><button class="chip" data-action="toggle-alert" data-id="${esc(a.id)}">${a.active?'Pause':'Rearm'}</button><button class="icon-button" data-action="delete-alert" data-id="${esc(a.id)}" aria-label="Delete alert">${icon('trash-2')}</button></article>`).join(''):empty('No price alerts','Create a threshold for an explicit exchange instrument.');}

function evaluateAlerts(instrument,value,observedAt){let changed=false;for(const a of workspace.alerts){if(!a.active||a.venue!==instrument.venue||a.symbol!==instrument.symbol)continue;const previous=alertPrices.get(a.id),observation=freshObservation(previous,value,observedAt);if(!observation)continue;alertPrices.set(a.id,observation);if(crossed(previous?.price,value,a.target,a.direction)){a.active=false;a.triggeredAt=new Date().toISOString();changed=true;toast(`${a.symbol} crossed ${a.direction} ${num(a.target,8)}`);}}if(changed){save();updateAlertCount();if(page==='workspace'){$('#alerts-list').innerHTML=alertList();hydrate();}}}

let alertBusy=false;async function pollAlerts(){if(document.hidden||alertBusy)return;const active=workspace.alerts.filter(a=>a.active);const unique=[...new Map(active.map(a=>[a.venue+':'+a.symbol,a])).values()].slice(0,10);alertBusy=true;await Promise.allSettled(unique.map(async a=>{try{const r=await api(`ticker?venue=${a.venue}&symbol=${a.symbol}`);if(r.cache==='stale')return;const value=+(r.data.lastPrice??r.data.last);if(Number.isFinite(value))evaluateAlerts(a,value,r.data.observedAt??r.fetchedAt);}catch{}}));alertBusy=false;}

function updateAlertCount(){const n=workspace.alerts.filter(a=>a.active).length;if($('#alert-count'))$('#alert-count').textContent=n?String(n):'';}



function modal(title,content,wide=false){modalGeneration++;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${content}</section></div>`;hydrate();setTimeout(()=>$('#modal-root input, #modal-root select, #modal-root button')?.focus(),0);}

function closeModal(){modalGeneration++;$('#modal-root').innerHTML='';}

function openSearch(){modal('Search',`<label class="command-search">${icon('search')}<input id="command-input" placeholder="Search Bitcoin, ETH, a trading pair…" autocomplete="off" aria-label="Search coins and instruments"></label><div id="command-results" class="command-results"></div><div class="modal-footer">Asset identity and venue symbols are shown separately. <kbd>ESC</kbd> to close.</div>`,true);$('#command-input').addEventListener('input',e=>searchResults(e.target.value));searchResults('');}

function searchResults(q){const query=q.toLowerCase(),assets=(data.markets?.data??[]).filter(a=>`${a.name} ${a.symbol} ${a.id}`.toLowerCase().includes(query)).slice(0,7),pairs=[...instruments.binance,...instruments.coinbase].filter(a=>`${a.base} ${a.symbol}`.toLowerCase().includes(query)).slice(0,8);$('#command-results').innerHTML=`<div class="eyebrow">Crypto assets · USD</div>${assets.map(a=>`<button class="command-row" data-action="asset-chart" data-id="${esc(a.id)}">${coinMark(a.symbol)}<span><strong>${esc(a.name)} <small>${esc(a.symbol)}</small></strong><small>${esc(a.id)}</small></span><b>${price(a.price)}</b>${icon('chevron-right')}</button>`).join('')||'<p class="muted">No directory match. Providers may still be connecting.</p>'}<div class="eyebrow">Exchange instruments</div>${pairs.map(a=>`<button class="command-row" data-action="select-instrument" data-venue="${a.venue}" data-symbol="${esc(a.symbol)}">${coinMark(a.base)}<span><strong>${esc(a.base)} / ${esc(a.quote)}</strong><small>${a.venue.toUpperCase()} spot · ${esc(a.symbol)}</small></span>${icon('arrow-up-right')}</button>`).join('')||'<p class="muted">No matching instrument in the loaded venues.</p>'}`;hydrate();}

function chooseAsset(id){const a=(data.markets?.data??[]).find(a=>a.id===id);if(!a)return;const matches=[...instruments.binance,...instruments.coinbase].filter(x=>x.base===a.symbol);modal(`${esc(a.name)} <span class="muted">${esc(a.symbol)}</span>`,`<div class="asset-detail"><div><small>Aggregate valuation · USD</small><strong>${price(a.price)}</strong><span class="${tone(a.change)}">${pct(a.change)} / 24h</span></div><p>Directory identity: <code>${esc(a.id)}</code><br>Provider updated ${esc(stamp(a.updatedAt))}</p></div><div class="callout">Choose an exchange instrument to open its own order book and OHLCV. A ticker match is not proof of token or contract identity; verify the venue listing.</div><div class="instrument-choices">${matches.length?matches.map(x=>`<button class="command-row" data-action="select-instrument" data-venue="${x.venue}" data-symbol="${esc(x.symbol)}">${coinMark(x.base)}<span><strong>${esc(x.base)} / ${esc(x.quote)}</strong><small>${x.venue.toUpperCase()} spot</small></span>${icon('arrow-up-right')}</button>`).join(''):empty('No matching chart instrument','This asset is not available in the current Binance USDT / Coinbase USD universe. No candles are synthesized.')}</div>`);}

function selectInstrument(venue,symbol){const i=instruments[venue].find(x=>x.symbol===symbol);if(!i){toast('Instrument is unavailable. Refresh the directory.');return;}flushNote();selected=i;closeModal();if(page==='terminal'){updateInstrumentOptions();$('#venue').value=venue;capturePreferences();resetRisk();terminal.load(selected,selectedInterval);loadNote();}else{workspace.preferences.lastInstrument=selected;save();location.hash='terminal';}}

function indicatorModal(){if(!terminal)return;modal('Indicators & chart settings',`<form id="indicator-form"><p class="muted">Calculated locally from this instrument's OHLCV. Warmup periods are omitted.</p><div class="indicator-options">${[['ema','EMA pair (configurable + 50)'],['sma','Simple moving average'],['bb','Bollinger Bands (2 standard deviations)'],['vwap','UTC-session VWAP']].map(([id,label])=>`<label><input type="checkbox" name="${id}" ${terminal.indicators[id]?'checked':''}>${label}</label>`).join('')}</div><label class="marker-setting"><input type="checkbox" name="markers" ${terminal.markers?'checked':''}> Show EMA 20/50 crossover markers (completed candles)</label><div class="form-grid"><label>Overlay period<input name="period" type="number" min="2" max="200" value="${terminal.period}" required></label><label>Oscillator pane<select name="oscillator">${['rsi','macd','volume','none'].map(x=>`<option value="${x}" ${terminal.oscillator===x?'selected':''}>${x.toUpperCase()}</option>`).join('')}</select></label><label>RSI period<input name="rsiPeriod" type="number" min="2" max="100" value="${terminal.rsiPeriod}" required></label></div><p class="data-note">VWAP is a typical-price OHLCV approximation. Heikin-Ashi changes displayed candles, not underlying indicator inputs. The technical-context panel uses fixed parameters separately.</p><button class="button primary" type="submit">Apply settings ${icon('check')}</button></form>`);$('#indicator-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);for(const k of Object.keys(terminal.indicators))terminal.indicators[k]=f.has(k);terminal.period=+f.get('period');terminal.rsiPeriod=+f.get('rsiPeriod');terminal.oscillator=f.get('oscillator');terminal.markers=f.has('markers');capturePreferences();if(terminal.bars.length)terminal.build();$('#indicator-strip').innerHTML=Object.entries(terminal.indicators).filter(([k,v])=>v).map(([k])=>`<span>${k.toUpperCase()} ${k==='vwap'?'UTC':terminal.period}${k==='ema'?' / 50':''}</span>`).join('')+`<span>${terminal.oscillator.toUpperCase()} ${terminal.oscillator==='rsi'?terminal.rsiPeriod:''}</span><small>UTC bars · provisional latest candle</small>`;refreshIndicatorStrip();closeModal();});}

function drawingModal(){if(!terminal)return;const drawings=workspace.drawings[terminal.key]??[];modal('Saved drawings',`<p class="muted">${esc(selected.symbol)} · ${selectedInterval.toUpperCase()} · Click a tool, then place anchors on the price pane. Dragging the chart preserves time/price anchors.</p><div class="drawing-list">${drawings.map(d=>`<form class="drawing-edit" data-id="${esc(d.id)}"><div><span class="small-tag">${d.type}</span><button type="button" class="icon-button" data-action="delete-drawing" data-id="${esc(d.id)}" aria-label="Delete drawing">${icon('trash-2')}</button></div><label>Annotation<input name="label" value="${esc(d.label)}" maxlength="100"></label>${d.points.map((p,i)=>`<div class="form-grid"><label>Anchor ${i+1} price<input type="number" name="price${i}" min="0.00000001" step="any" value="${p.price}" required></label><label>Anchor ${i+1} UTC<input type="datetime-local" name="time${i}" value="${new Date(p.time*1000).toISOString().slice(0,16)}" required></label></div>`).join('')}<button class="button" type="submit">Update drawing</button></form>`).join('')||empty('No drawings yet','Use horizontal, trend, Fibonacci or annotation tools on the price chart.')}<div class="data-note">Date fields are UTC. Set anchor times to existing candle openings to keep them visible.</div></div>`);document.querySelectorAll('.drawing-edit').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const d=drawings.find(x=>x.id===f.dataset.id),values=new FormData(f);d.label=String(values.get('label'));d.points=d.points.map((p,i)=>({price:+values.get('price'+i),time:Date.parse(values.get('time'+i)+':00Z')/1000}));save();terminal.draw();toast('Drawing updated.');}));}

function alertModal(){const count=workspace.alerts.filter(x=>x.active).length;if(count>=10){toast('Pause an alert before adding another (10 active instruments maximum).');return;}modal('Create a price alert',`<form id="alert-form"><p class="muted">${esc(selected.venue.toUpperCase())} · ${esc(selected.base)} / ${esc(selected.quote)}</p><div class="form-grid"><label>When price crosses<select name="direction"><option value="above">Above</option><option value="below">Below</option></select></label><label>Target (${esc(selected.quote)})<input name="target" type="number" min="0.00000001" step="any" value="${terminal?.quote?.price??''}" placeholder="Target price" required></label></div><div class="callout">Keep this tab open. First quote establishes a baseline; a later crossing triggers the alert once. This is an in-app alert, not a background notification.</div><button class="button primary" type="submit">Arm alert ${icon('bell')}</button></form>`);$('#alert-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);workspace.alerts.push({id:crypto.randomUUID(),venue:selected.venue,symbol:selected.symbol,direction:f.get('direction'),target:+f.get('target'),active:true,last:null});save();closeModal();toast('Alert armed. Keep CRYPTOZ open to monitor.');updateAlertCount();if(page==='workspace')renderPage();pollAlerts();});}

document.addEventListener('click',e=>{

 if(e.target.closest('[data-nav]'))document.body.classList.remove('menu-open');const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;

 if(a==='skip-content'){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}

 if(b.closest('.chart-menu'))b.closest('.chart-menu').open=false;
 if(a==='zoom-in'){terminal?.zoom(2/3);return;}if(a==='zoom-out'){terminal?.zoom(1.5);return;}if(a==='focus-chart'){setChartFocus(!document.body.classList.contains('chart-focus'));return;}
 if(a==='dock-expand'||a==='dock-toggle'){setDock(dockMode==='expanded'?'compact':dockMode==='hidden'?'compact':'expanded');return;}
 if(a==='dock-hide'){setDock('hidden');$('[data-action="dock-toggle"]').focus();return;}
 if(a==='section'){const target=document.getElementById(b.dataset.target);if(target){const reduced=appearance.motion==='reduced'||matchMedia('(prefers-reduced-motion: reduce)').matches;target.scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});if(b.closest('.context-nav')){b.closest('.context-nav').querySelectorAll('[data-action="section"]').forEach(x=>x.setAttribute('aria-pressed',x===b));}if(target.matches('input,textarea,select'))target.focus({preventScroll:true});}return;}
 if(a==='appearance'){appearanceModal();return;}if(a==='live-chart'){selected=instruments.binance.find(x=>x.symbol===b.dataset.symbol)??selected;if(page==='terminal')renderPage();else location.hash='terminal';return;}if(a==='menu'){document.body.classList.toggle('menu-open');return;}

 if(a==='search'){openSearch();return;}if(a==='close-modal'){closeModal();return;}

 if(a==='refresh'){if(page==='learn'){learning?.refresh();return;}fetchData(page==='studio'?['markets','global','sentiment','news','chains']:page==='markets'&&marketUniverse==='exchange'?['exchange']:['markets','global','sentiment','news']);return;}

 if(a==='watch'){const id=b.dataset.id;if(workspace.watchlist.includes(id))workspace.watchlist=workspace.watchlist.filter(x=>x!==id);else if(workspace.watchlist.length<200)workspace.watchlist.push(id);save();b.classList.toggle('selected',workspace.watchlist.includes(id));b.setAttribute('aria-pressed',workspace.watchlist.includes(id));if(page==='workspace')updateWorkspacePrices();return;}

 if(a==='view-watchlist'){onlyWatch=true;location.hash='markets';return;}

 if(a==='asset-chart'){chooseAsset(b.dataset.id);return;}

 if(a==='exchange-chart'){selectInstrument('binance',b.dataset.id);return;}

 if(a==='select-instrument'){selectInstrument(b.dataset.venue,b.dataset.symbol);return;}

 if(a==='default-chart'){selected={venue:'binance',symbol:'BTCUSDT',base:'BTC',quote:'USDT'};return;}

 if(a==='universe'){marketUniverse=b.dataset.universe;if(marketUniverse==='exchange'&&marketSort==='marketCap')marketSort='volume';marketPage=0;renderMarkets();hydrate();return;}

 if(a==='toggle-watch'){onlyWatch=!onlyWatch;b.classList.toggle('selected',onlyWatch);marketPage=0;renderMarketResults();return;}

 if(a==='prev-page'||a==='next-page'){marketPage+=a==='next-page'?1:-1;renderMarketResults();return;}

 if(a==='export-markets'){const list=filteredMarkets();const clean=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('cryptoz-markets.csv','id,symbol,name,price,quote,change24h,marketCap,volume,updatedAt\n'+list.map(x=>[x.id,x.symbol,x.name,x.price,marketUniverse==='exchange'?'USDT':'USD',x.change,x.marketCap,x.volume,x.updatedAt].map(clean).join(',')).join('\n'),'text/csv');return;}

 if(a==='news-more'){newsLimit+=20;renderNewsResults();return;}if(a==='news-source'){newsSource=b.dataset.source;newsLimit=20;document.querySelectorAll('[data-action="news-source"]').forEach(x=>{x.classList.toggle('active',x.dataset.source===newsSource);x.setAttribute('aria-pressed',x.dataset.source===newsSource);});renderNewsResults();return;}

 if(a==='studio-tab'){studioView(b.dataset.view);return;}

 if(a==='timeframe'){selectedInterval=b.dataset.time;if($('#compact-interval'))$('#compact-interval').value=selectedInterval;capturePreferences();document.querySelectorAll('[data-time]').forEach(el=>el.classList.toggle('selected',el.dataset.time===selectedInterval));terminal?.load(selected,selectedInterval);return;}

 if(a==='retry-chart'){terminal?.load(selected,selectedInterval);return;}

 if(a==='layouts'){layoutModal();return;}

 if(a==='load-layout'){const l=workspace.layouts.find(x=>x.id===b.dataset.id);if(!l)return;flushNote();workspace.preferences=normalizePreferences(l.settings);selected=workspace.preferences.lastInstrument;selectedInterval=workspace.preferences.interval;save();closeModal();renderPage();return;}

 if(a==='delete-layout'){workspace.layouts=workspace.layouts.filter(x=>x.id!==b.dataset.id);save();layoutModal();return;}

 if(a==='indicators'){indicatorModal();return;}

 if(a==='fit-chart'){terminal?.setViewPreset('all');capturePreferences();return;}

 if(a==='chart-csv'){terminal?.exportCSV();return;}if(a==='chart-png'){terminal?.exportPNG();return;}

 if(a==='draw-tool'){terminal?.setTool(b.dataset.tool,b.dataset.tool==='label'?'Research note':'');document.querySelectorAll('[data-tool]').forEach(el=>el.classList.toggle('selected',el===b));if(b.dataset.tool!=='cursor')toast(b.dataset.tool==='trend'||b.dataset.tool==='fib'?'Click two anchors on the price pane.':'Click a level on the price pane.');return;}

 if(a==='drawings'){drawingModal();return;}

 if(a==='delete-drawing'){workspace.drawings[terminal.key]=(workspace.drawings[terminal.key]??[]).filter(x=>x.id!==b.dataset.id);save();terminal.draw();$('#drawings-count').textContent=workspace.drawings[terminal.key].length;drawingModal();return;}

 if(a==='use-price'){if(terminal?.quote?.price){$('#risk-form [name="entry"]').value=terminal.quote.price;}else toast('Wait for a valid quote.');return;}

 if(a==='save-note'){workspace.notes[`${selected.venue}:${selected.symbol}`]=$('#research-note').value;const ok=save();$('#note-status').textContent=ok?'Saved on this browser':'Not saved · export a backup';if(ok)toast('Research note saved.');return;}

 if(a==='new-alert'){alertModal();return;}

 if(a==='toggle-alert'){const x=workspace.alerts.find(x=>x.id===b.dataset.id);if(!x.active&&workspace.alerts.filter(a=>a.active).length>=10){toast('Maximum 10 active alerts.');return;}x.active=!x.active;alertPrices.delete(x.id);save();renderPage();return;}

 if(a==='delete-alert'){workspace.alerts=workspace.alerts.filter(x=>x.id!==b.dataset.id);alertPrices.delete(b.dataset.id);save();renderPage();return;}

 if(a==='delete-journal'){workspace.journal=workspace.journal.filter(x=>x.id!==b.dataset.id);save();renderPage();return;}

 if(a==='restore-workspace'){try{workspace=validateWorkspace(JSON.parse(storage.getItem(RECOVERY_KEY)));selected=workspace.preferences.lastInstrument;selectedInterval=workspace.preferences.interval;save();renderPage();toast('Pre-import workspace restored.');}catch{toast('No valid recovery backup is available.');}return;}

 if(a==='export-workspace'){download('cryptoz-workspace.json',JSON.stringify(workspace,null,2),'application/json');return;}

 if(a==='import-workspace'){$('#workspace-file')?.click();return;}

});

document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.chart-menu[open]').forEach(d=>d.open=false);if(document.body.classList.contains('chart-focus'))setChartFocus(false);closeModal();terminal?.setTool('cursor');document.body.classList.remove('menu-open');}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}if(e.key==='Tab'&&$('#modal-root .modal')){const focusable=[...$('#modal-root .modal').querySelectorAll('button,input,select,a[href],textarea')].filter(x=>!x.disabled),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

$('#modal-root').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});

window.addEventListener('resize',syncDockAccess);window.addEventListener('beforeunload',flushNote);window.addEventListener('storage',e=>{if(e.key==='cryptoz.workspace.v2')toast('Workspace changed in another tab. Export this tab before reloading if it contains unsaved research.');});window.addEventListener('hashchange',route);window.addEventListener('online',()=>{toast('Internet connection restored.');fetchData();});window.addEventListener('offline',()=>toast('Internet disconnected. Displayed data may become stale.'));

